{
  "description": "Expected JSON structure for --addresses flag",
  "fileFormat": "JSON array of Stellar public key addresses",
  "example": [
    "GCDVWDVSFNX43HOAIMRLPHJAQMPRRDZGRUE6DM6IFSV35BBNMGEZ662M",
    "GD3AQAE6KUU4W4OMO6QU5LC5MA3E2IQETW6LR2BUHSQE4MNQYAZR6WPS",
    "GDUMBFZF42V5HQCHSHZE3UHUUMDJPPLA6YLFAQG7NWAUHZBZSBJY4AT3"
  ],
  "notes": [
    "Each entry must be a valid 56-character Stellar public key (G prefix)",
    "Duplicates are allowed; they will be checked individually",
    "Invalid addresses will cause the script to fail with a clear error",
    "See test/fixtures/addresses.json for a real example"
  ],
  "mockProviderBehavior": {
    "description": "The MockSanctionsProvider flags the first address in the example list",
    "flaggedAddresses": ["GCDVWDVSFNX43HOAIMRLPHJAQMPRRDZGRUE6DM6IFSV35BBNMGEZ662M"]
  }
}

{
  "description": "CLI flags for node dist/sync.js",
  "flags": [
    {
      "name": "--addresses",
      "type": "string (file path)",
      "required": true,
      "description": "Path to JSON file containing array of Stellar addresses to check",
      "example": "--addresses ./addresses.json"
    },
    {
      "name": "--dry-run",
      "type": "boolean flag",
      "required": false,
      "description": "Run in dry-run mode (check addresses, log planned actions, do not submit transactions)",
      "example": "--dry-run",
      "default": "false"
    },
    {
      "name": "--contract-id",
      "type": "string (contract address)",
      "required": "if not using --dry-run",
      "description": "Soroban contract ID (denylist-gate) to submit transactions to",
      "example": "--contract-id CABCDEF..."
    },
    {
      "name": "--rpc-url",
      "type": "string (URL)",
      "required": "if not using --dry-run",
      "description": "Soroban RPC endpoint URL",
      "example": "--rpc-url https://soroban-testnet.stellar.org"
    },
    {
      "name": "--network-passphrase",
      "type": "string",
      "required": "if not using --dry-run",
      "description": "Network passphrase (must match the network of the RPC endpoint)",
      "example": "--network-passphrase 'Test SDF Network ; September 2015'",
      "commonValues": [
        "Test SDF Network ; September 2015 (testnet)",
        "Public Global Stellar Network ; September 2015 (mainnet)"
      ]
    },
    {
      "name": "--secret-key",
      "type": "string (secret key)",
      "required": "if not using --dry-run",
      "description": "Stellar secret key (starts with 'S') for the account that will fund and sign transactions. Must have XLM balance to cover fees.",
      "example": "--secret-key SABCDEF...",
      "security": "NEVER commit or log this value. Use environment variables in production."
    }
  ],
  "exitCodes": [
    {
      "code": 0,
      "meaning": "Success"
    },
    {
      "code": 1,
      "meaning": "Error (missing required flags, invalid JSON, network error, etc.)"
    }
  ]
}
